{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "Levocetirizine, a zwitterionic antihistamine with a basic piperazine and carboxylic acid, showed the lowest cerebral H1-receptor occupancy by PET and a low ability to cross the BBB, directly supporting a fail prediction for the query's zwitterionic piperidine-carboxylic acid scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Bepotastine, which combines a basic piperidine with a carboxylic acid side chain, showed only 16.6% brain H1 receptor occupancy and was classified as low permeability, indicating minimal CNS access despite some penetration; this supports fail.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Enalapril, a zwitterionic carboxylic acid-containing drug, achieved only low levels in rat brain and CSF after systemic dosing, supporting the expectation that the query's ionized acid/amine will limit CNS exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "In a high-transfer CSF study, sufentanil, a basic piperidine/ether-containing molecule, had CSF concentrations below detection after intravenous injection, suggesting that heteroatom-rich piperidine scaffolds can show poor CSF exposure; this supports fail.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "A structurally related zwitterionic piperidine-quinolone carboxylic acid showed a CSF/unbound-plasma ratio of 0.7 and was labeled permeable in rat, providing a counterexample that some zwitterionic acids can achieve meaningful CSF exposure; this tempers the fail prediction.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a zwitterionic, fully ionized molecule with very low estimated logD and high molecular weight. The most transferable experimental evidence from zwitterionic piperidine/piperazine carboxylic acids (levocetirizine, bepotastine, enalapril) consistently shows poor CNS exposure. A single quinolone-acid counterexample with CSF/plasma 0.7 does not outweigh the overall fail direction.",
  "evidence_gaps": [
    "No direct brain, CSF, or receptor-occupancy data exist for the exact query molecule.",
    "Active uptake or efflux transporter substrate status for the query is unknown.",
    "CSF measurements may not fully reflect brain tissue exposure, especially for lipophilic or transporter-dependent compounds.",
    "Species differences and unbound versus total concentration interpretations add uncertainty."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

